<script>
(function () {
  'use strict';

  var form = document.getElementById('signup-form');
  var success = document.getElementById('success');
  var successText = document.getElementById('success-text');
  var toggle = document.getElementById('toggle-password');
  var fields = ['name', 'email', 'website', 'password'].map(function (id) {
    return document.getElementById(id);
  });

  // Use our own validation and messages instead of the browser's bubbles.
  form.noValidate = true;

  // Returns a URL object for a valid http(s) address, or null.
  // A missing scheme is tolerated ("example.com" is read as "https://example.com").
  function parseWebsite(value) {
    var text = value.trim();
    if (!/^https?:\/\//i.test(text)) {
      text = 'https://' + text;
    }
    var url;
    try {
      url = new URL(text);
    } catch (e) {
      return null;
    }
    if (url.username || url.password) {
      return null;
    }
    var labels = url.hostname.split('.');
    var tld = labels[labels.length - 1];
    var hasEmptyLabel = labels.some(function (label) { return label === ''; });
    if (labels.length < 2 || hasEmptyLabel || tld.length < 2 || /^\d+$/.test(tld)) {
      return null;
    }
    return url;
  }

  // Each validator returns an error message, or an empty string when valid.
  var validators = {
    name: function (value) {
      var v = value.trim();
      if (!v) return 'Enter your full name.';
      if (v.length < 2 || !/\p{L}/u.test(v)) return 'Enter a valid name (at least 2 characters).';
      if (v.length > 100) return 'Name must be 100 characters or fewer.';
      return '';
    },
    email: function (value) {
      var v = value.trim();
      if (!v) return 'Enter your email address.';
      if (v.length > 254 || !/^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(v)) {
        return 'Enter a valid email address, like name@example.com.';
      }
      return '';
    },
    website: function (value) {
      var v = value.trim();
      if (!v) return ''; // optional field
      if (!parseWebsite(v)) return 'Enter a valid web address, like https://example.com.';
      return '';
    },
    password: function (value) {
      if (!value) return 'Enter a password.';
      if (value.length < 8) return 'Password must be at least 8 characters.';
      if (!/\p{L}/u.test(value) || !/\d/.test(value)) {
        return 'Password must include at least one letter and one number.';
      }
      return '';
    }
  };

  function setError(input, message) {
    var error = document.getElementById(input.id + '-error');
    error.textContent = message;
    error.hidden = !message;
    if (message) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
  }

  function validateField(input) {
    var message = validators[input.name](input.value);
    setError(input, message);
    return !message;
  }

  fields.forEach(function (input) {
    // Check a field when the user leaves it, but don't nag about fields
    // they have only tabbed through without typing anything.
    input.addEventListener('blur', function () {
      if (input.value !== '' || input.hasAttribute('aria-invalid')) {
        validateField(input);
      }
    });
    // Once a field shows an error, clear it as soon as the value is fixed.
    input.addEventListener('input', function () {
      if (input.hasAttribute('aria-invalid')) {
        validateField(input);
      }
    });
  });

  toggle.addEventListener('click', function () {
    var password = document.getElementById('password');
    var show = password.type === 'password';
    password.type = show ? 'text' : 'password';
    toggle.textContent = show ? 'Hide' : 'Show';
    toggle.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
  });

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var firstInvalid = null;
    fields.forEach(function (input) {
      if (!validateField(input) && !firstInvalid) {
        firstInvalid = input;
      }
    });

    if (firstInvalid) {
      firstInvalid.focus();
      return;
    }

    var data = {
      name: form.elements.name.value.trim(),
      email: form.elements.email.value.trim(),
      website: form.elements.website.value.trim(),
      password: form.elements.password.value
    };
    if (data.website && !/^https?:\/\//i.test(data.website)) {
      data.website = 'https://' + data.website;
    }

    // All fields are valid. This page has no backend, so it only shows a
    // confirmation. To send the data for real, replace the lines below with
    // a request to your server, e.g. fetch('/signup', { method: 'POST', ... }),
    // and always repeat the validation on the server.
    successText.textContent =
      'Thanks, ' + data.name.split(/\s+/)[0] + '. We have your details for ' + data.email + '.';
    form.hidden = true;
    success.hidden = false;
    success.focus();
  });
})();
</script>
